void generate_download_path(uint32_t download_id, const content_DownloadTargetCallback* callback, const base_FilePath* suggested_path) {
    // Ensure the function is called on the UI thread
    DCHECK_CURRENTLY_ON(BrowserThread::UI);

    // Create a new file name with ".crdownload" extension
    base_FilePath new_path = base_FilePath_ReplaceExtension(suggested_path, base_FilePath_FromString(".crdownload"));

    // Prepare the download target information
    DownloadTargetCallback_Info info;
    info.path = new_path;
    info.disposition = TARGET_DISPOSITION_DEFAULT;
    info.danger_type = DANGEROUS_CONTENT;
    info.had_target_disposition = true;
    info.is_download_in_progress = true;

    // Invoke the callback with the generated path and metadata
    callback->Run(download_id, &info);
}

void generate_download_path(uint32_t download_id, const content_DownloadTargetCallback* callback, const base_FilePath* suggested_path) {
  // Assume this thread check is handled by the UI thread assertion
  base_FilePath path = *suggested_path;
  char* filename = path.filename;
  size_t len = strlen(filename);
  char* new_filename = (char*)malloc(len + 13); // Length for ".crdownload" + 1

  strcpy(new_filename, filename);
  strcat(new_filename, ".crdownload");

  base_FilePath new_path = path;
  new_path.filename = new_filename;

  // Assume that the callback is called with the new path and appropriate disposition and danger type
  callback->Run(download_id, &new_path, TARGET_DISPOSITION_USE_SUGGESTED_PATH, DANGER_TYPE_NOT_DANGEROUS);

  free(new_filename);
}

void generate_download_path(uint32_t download_id, const content_DownloadTargetCallback* callback, const base_FilePath* suggested_path) {
    // Ensure that the function is called on the UI thread
    if (!is_ui_thread()) {
        return;
    }

    // Create a new file name with ".crdownload" extension to indicate the download is in progress
    char* new_file_name = malloc(strlen(suggested_path->value) + 12); // Allow for ".crdownload" extension
    strcpy(new_file_name, suggested_path->value);
    strcat(new_file_name, ".crdownload");

    // Prepare the path for the callback
    base_FilePath new_path;
    new_path.value = new_file_name;

    // Specify the target disposition, danger type, and invoke the callback with the new path
    content_DownloadTargetCallback_Invoke(callback, &new_path, TARGET_DISPOSITION_DEFAULT, DANGER_TYPE_NOT_DANGEROUS);

    // Free the allocated memory for the new file name
    free(new_file_name);
}
